window.docContents[96].resolve({"/Judgments-and-domains/#Core-C______--Judgments-and-domains":{"contents":"Core C++ has three semantic components and four judgments. The typing context  maps identifiers to types. The environment  maps identifiers to locations . The store  maps locations to values, and its domain is the set of live locations. The notation is the sequent style of Kahn (1987). Hypotheses stand left of , the subject right of it, and the result after .\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Core C++","header":"1. Judgments and domains","id":"/Judgments-and-domains/#Core-C______--Judgments-and-domains"}});